#!/usr/bin/env python3
"""Generates the code-page and transliteration tables for SwiftESCPOS.

The upper halves (0x80-0xFF) of each code page come from Python's own codecs, so
no byte is typed in by hand. Run from the package root:

    python3 -I Scripts/generate-code-pages.py

and commit the regenerated Swift files.
"""

import unicodedata
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
EXTENSIONS = ROOT / "Sources/SwiftESCPOS/Backend/Extensions/Types"

HEADER = """//
//  {name}
//  swift-escpos
//
//  Generated by Scripts/generate-code-pages.py. Do not edit by hand.
//
"""

CODE_PAGES = [
    ("pc437", "cp437"),
    ("pc850", "cp850"),
    ("pc858", "cp858"),
    ("windows1252", "cp1252"),
]


def scalar(character):
    return f"0x{ord(character):04X}"


def code_page_tables():
    lines = [HEADER.format(name="ESCPOSCodePage+Tables.swift"), "extension ESCPOSCodePage {"]
    for case, codec in CODE_PAGES:
        entries = []
        for byte in range(0x80, 0x100):
            try:
                entries.append(scalar(bytes([byte]).decode(codec)))
            except UnicodeDecodeError:
                entries.append("nil")
        lines.append(f"    /// The Unicode scalars of `{codec}` bytes 0x80-0xFF, in byte order; `nil` is undefined.")
        lines.append(f"    static let {case}UpperHalf: [UInt32?] = [")
        for row in range(0, 128, 8):
            lines.append("        " + ", ".join(entries[row:row + 8]) + ",")
        lines.append("    ]")
        lines.append("")
    lines[-1] = "}"
    return "\n".join(lines) + "\n"


# Replacements for characters a code page may not hold. Accented Latin letters fall
# back to their base letter, derived from Unicode decomposition; the rest is listed.
EXTRA = {
    "€": "EUR", "‘": "'", "’": "'", "‚": "'", "‛": "'",
    "“": '"', "”": '"', "„": '"', "–": "-", "—": "-",
    "…": "...", "•": "*", " ": " ", " ": " ", " ": " ",
    "Œ": "OE", "œ": "oe", "Æ": "AE", "æ": "ae", "ß": "ss",
    "Ø": "O", "ø": "o", "Ł": "L", "ł": "l", "Ð": "D",
    "ð": "d", "Þ": "Th", "þ": "th", "×": "x", "™": "TM",
    "©": "(c)", "®": "(R)", "−": "-", "·": ".",
}


def transliterations():
    table = dict(EXTRA)
    for code in range(0x00C0, 0x0250):
        character = chr(code)
        if character in table:
            continue
        base = unicodedata.normalize("NFD", character)[0]
        if base != character and base.isascii() and base.isalpha():
            table[character] = base
    lines = [
        HEADER.format(name="ESCPOSTransliteration+Table.swift"),
        "extension ESCPOSTransliteration {",
        "    /// Replacements for scalars a code page cannot hold, keyed by Unicode scalar value.",
        "    static let table: [UInt32: String] = [",
    ]
    for character in sorted(table, key=ord):
        replacement = table[character].replace("\\", "\\\\").replace('"', '\\"')
        lines.append(f'        {scalar(character)}: "{replacement}",  // {unicodedata.name(character, "?").lower()}')
    lines.append("    ]")
    lines.append("}")
    return "\n".join(lines) + "\n"


def main():
    for folder in ("ESCPOSCodePage", "ESCPOSTransliteration"):
        (EXTENSIONS / folder).mkdir(parents=True, exist_ok=True)
    (EXTENSIONS / "ESCPOSCodePage/ESCPOSCodePage+Tables.swift").write_text(code_page_tables())
    (EXTENSIONS / "ESCPOSTransliteration/ESCPOSTransliteration+Table.swift").write_text(transliterations())


if __name__ == "__main__":
    main()
